      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Sample Card' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    const viewerEmail = `e2e-us5-viewer-${Date.now()}@example.com`
    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed-board-member`, {
      data: { email: viewerEmail, boardId: board.id, role: 'Viewer' },
    })
    expect(seedResp.ok(), `Seed viewer failed: ${seedResp.status()}`).toBeTruthy()

    const viewerCtx = await browser.newContext()
    const viewerPage = await viewerCtx.newPage()
    await viewerPage.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(viewerEmail)}&displayName=Viewer+User`,
    )
    await viewerPage.waitForURL(`${WEB_BASE}/**`)

    await viewerPage.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(viewerPage.getByRole('heading', { name: board.name })).toBeVisible({
      timeout: 10_000,
    })

    // Lane and card content is visible
    await expect(viewerPage.getByRole('region', { name: /lane: backlog/i })).toBeVisible()
    await expect(viewerPage.getByText('Sample Card')).toBeVisible()

    // Write controls are hidden
    await expect(viewerPage.getByRole('button', { name: /add lane/i })).not.toBeVisible()
    await expect(viewerPage.getByRole('button', { name: /add card/i })).not.toBeVisible()
    await expect(viewerPage.getByRole('button', { name: /edit card/i })).not.toBeVisible()
    await expect(viewerPage.getByRole('button', { name: /delete card/i })).not.toBeVisible()
    await expect(viewerPage.getByRole('button', { name: /delete lane/i })).not.toBeVisible()
    await expect(viewerPage.getByRole('button', { name: /drag to reorder/i })).not.toBeVisible()

    await viewerCtx.close()
  })

  test('scenario 2 — viewer direct API write attempts all return 403', async ({
    request,
    browser,
  }) => {
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Viewer API Board ${Date.now()}` },
    })
    expect(boardResp.ok()).toBeTruthy()
    const board = await boardResp.json()

    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'To Do' },
    })
    expect(laneResp.ok()).toBeTruthy()
    const lane = await laneResp.json()

    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Existing Card' } },
    )
    expect(cardResp.ok()).toBeTruthy()
    const card = await cardResp.json()

    const viewerEmail = `e2e-us5-api-viewer-${Date.now()}@example.com`
    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed-board-member`, {
      data: { email: viewerEmail, boardId: board.id, role: 'Viewer' },
    })
    expect(seedResp.ok(), `Seed viewer failed: ${seedResp.status()}`).toBeTruthy()

    const viewerCtx = await browser.newContext()
    const viewerPage = await viewerCtx.newPage()
    await viewerPage.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(viewerEmail)}&displayName=Viewer+User`,
    )
    await viewerPage.waitForURL(`${WEB_BASE}/**`)

    const api = viewerPage.request

    // Create lane — 403
    const createLaneResp = await api.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Viewer Lane' },
    })
    expect(createLaneResp.status(), 'create lane should be 403').toBe(403)

    // Rename lane — 403
    const renameLaneResp = await api.patch(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}`,
      { data: { name: 'Renamed' } },
    )
    expect(renameLaneResp.status(), 'rename lane should be 403').toBe(403)

    // Move lane — 403
    const moveLaneResp = await api.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/move`,
      { data: { targetPosition: 1, expectedVersion: lane.version } },
    )
    expect(moveLaneResp.status(), 'move lane should be 403').toBe(403)

    // Delete lane — 403
    const deleteLaneResp = await api.delete(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}`,
    )
    expect(deleteLaneResp.status(), 'delete lane should be 403').toBe(403)

    // Create card — 403
    const createCardResp = await api.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Viewer Card' } },
    )
    expect(createCardResp.status(), 'create card should be 403').toBe(403)

    // Update card — 403
    const updateCardResp = await api.patch(
      `${API_BASE}/api/v1/boards/${board.id}/cards/${card.id}`,
      { data: { title: 'Updated' } },
    )
    expect(updateCardResp.status(), 'update card should be 403').toBe(403)

    // Move card — 403
    const moveCardResp = await api.post(
      `${API_BASE}/api/v1/boards/${board.id}/cards/${card.id}/move`,
      { data: { targetLaneId: lane.id, targetPosition: 1, expectedVersion: card.version } },
    )
    expect(moveCardResp.status(), 'move card should be 403').toBe(403)

    // Delete card — 403
    const deleteCardResp = await api.delete(
      `${API_BASE}/api/v1/boards/${board.id}/cards/${card.id}`,
    )
    expect(deleteCardResp.status(), 'delete card should be 403').toBe(403)

    await viewerCtx.close()
  })
})

import { useState } from 'react'
import {
  Button,
  FluentProvider,
  Spinner,
  Title1,
  makeStyles,
  tokens,
  webLightTheme,
} from '@fluentui/react-components'
import { useParams } from 'react-router-dom'
import { useBoard } from '../hooks/useBoard'
import KanbanBoard from '../components/board/KanbanBoard'
import BoardMembersPanel from '../components/board/BoardMembersPanel'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalXXL,
    overflowX: 'auto',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: tokens.spacingVerticalL,
  },
  membersPanel: {
    marginTop: tokens.spacingVerticalL,
  },
})

export default function BoardPage() {
  const styles = useStyles()
  const { boardId } = useParams<{ boardId: string }>()
  const { data: board, isPending } = useBoard(boardId ?? '')
  const [membersOpen, setMembersOpen] = useState(false)

  if (isPending) return <Spinner label="Loading board…" />

  if (!board) return null

  const isOwner = board.callerRole === 'Owner'

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <div className={styles.header}>
          <Title1 as="h1">{board.name}</Title1>
          {isOwner && (
            <Button onClick={() => setMembersOpen((o) => !o)} aria-label="Members">
              Members
            </Button>
          )}
        </div>

        {isOwner && membersOpen && (
          <div className={styles.membersPanel}>
            <BoardMembersPanel boardId={board.id} callerRole={board.callerRole} />
          </div>
        )}

        <KanbanBoard board={board} />
      </div>
    </FluentProvider>
  )
}

import { useId, useState } from 'react'
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter,
} from '@dnd-kit/core'
import type { DragEndEvent, DragStartEvent, DragCancelEvent } from '@dnd-kit/core'
import {
  SortableContext,
  horizontalListSortingStrategy,
  sortableKeyboardCoordinates,
} from '@dnd-kit/sortable'
import {
  makeStyles,
  tokens,
  Toast,
  ToastBody,
  ToastTitle,
  Toaster,
  useToastController,
} from '@fluentui/react-components'
import type { BoardDetail, Card, Lane as LaneData } from '../../hooks/useBoard'
import { useMoveCard } from '../../hooks/useMoveCard'
import { useMoveLane } from '../../hooks/useMoveLane'
import Lane from './Lane'
import CardDragPreview from './CardDragPreview'
import LaneDragPreview from './LaneDragPreview'
import AddLaneForm from './AddLaneForm'
import { useDeleteLane } from '../../hooks/useDeleteLane'

const useStyles = makeStyles({
  lanes: {
    display: 'flex',
    gap: tokens.spacingHorizontalM,
    alignItems: 'flex-start',
    overflowX: 'auto',
    paddingBottom: tokens.spacingVerticalM,
  },
  instructions: {
    position: 'absolute',
    width: '1px',
    height: '1px',
    padding: '0',
    margin: '-1px',
    overflow: 'hidden',
    clip: 'rect(0,0,0,0)',
    whiteSpace: 'nowrap',
    border: '0',
  },
})

interface KanbanBoardProps {
  board: BoardDetail
}

type ActiveItem = { type: 'card'; item: Card } | { type: 'lane'; item: LaneData } | null

export default function KanbanBoard({ board }: KanbanBoardProps) {
  const styles = useStyles()
  const instructionsId = useId()
  const toasterId = useId()
  const { dispatchToast } = useToastController(toasterId)
  const [activeItem, setActiveItem] = useState<ActiveItem>(null)

  const canModify = board.callerRole === 'Owner' || board.callerRole === 'Member'

  const moveCard = useMoveCard()
  const moveLane = useMoveLane()
  const deleteLane = useDeleteLane()

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const sortedLanes = [...board.lanes].sort((a, b) => a.position - b.position)
  const laneIds = sortedLanes.map((l) => l.id)

  const handleDragStart = ({ active }: DragStartEvent) => {
    const card = board.lanes.flatMap((l) => l.cards).find((c) => c.id === active.id)
    if (card) {
      setActiveItem({ type: 'card', item: card })
      return
    }
    const lane = board.lanes.find((l) => l.id === active.id)
    if (lane) {
      setActiveItem({ type: 'lane', item: lane })
    }
  }

  const handleDragCancel = () => {
    setActiveItem(null)
  }

  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    setActiveItem(null)
    if (!over || active.id === over.id) return

    const draggingCard = board.lanes.flatMap((l) => l.cards).find((c) => c.id === active.id)
    if (draggingCard) {
      // Determine target lane and position
      const overCard = board.lanes.flatMap((l) => l.cards).find((c) => c.id === over.id)
      const overLane = board.lanes.find((l) => l.id === over.id)
      const targetLaneId = overCard?.laneId ?? overLane?.id ?? draggingCard.laneId
      const targetLane = board.lanes.find((l) => l.id === targetLaneId)
      if (!targetLane) return
      const targetPosition = overCard ? overCard.position : targetLane.cards.length + 1
      moveCard.mutate(
        {
          boardId: board.id,
          cardId: draggingCard.id,
          targetLaneId,
          targetPosition,
          expectedVersion: draggingCard.version,
        },
        {
          onError: () =>
            dispatchToast(
              <Toast>
                <ToastTitle>Move failed</ToastTitle>
                <ToastBody>The card could not be moved. Please try again.</ToastBody>
              </Toast>,
              { intent: 'error', pauseOnHover: true }
            ),
        }
      )
      return
    }

    const draggingLane = board.lanes.find((l) => l.id === active.id)
    if (draggingLane) {
      const overLane = board.lanes.find((l) => l.id === over.id)
      if (!overLane) return
      moveLane.mutate(
        {
          boardId: board.id,
          laneId: draggingLane.id,
          targetPosition: overLane.position,
          expectedVersion: draggingLane.version,
        },
        {
          onError: () =>
            dispatchToast(
              <Toast>
                <ToastTitle>Move failed</ToastTitle>
                <ToastBody>The lane could not be moved. Please try again.</ToastBody>
              </Toast>,
              { intent: 'error', pauseOnHover: true }
            ),
        }
      )
    }
  }

  const announcements = {
    onDragStart: ({ active }: DragStartEvent) =>
      `Picked up item ${active.id}. Use arrow keys to move, Space to drop, Escape to cancel.`,
    onDragOver: () => ``,
    onDragEnd: ({ active, over }: DragEndEvent) =>
      over ? `Dropped ${active.id} at position near ${over.id}.` : `Drop cancelled.`,
    onDragCancel: ({ active }: DragCancelEvent) => `Move cancelled for ${active.id}.`,
  }

  return (
    <>
      <Toaster toasterId={toasterId} position="bottom-end" />
      <span id={instructionsId + '-drag-instructions'} className={styles.instructions}>
        Press Space or Enter to start dragging. Use arrow keys to move. Press Space or Enter to
        drop, or Escape to cancel.
      </span>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
        accessibility={{ announcements }}
      >
        <SortableContext items={laneIds} strategy={horizontalListSortingStrategy}>
          <div className={styles.lanes}>
            {sortedLanes.map((lane) => (
              <Lane
                key={lane.id}
                lane={lane}
                callerRole={board.callerRole}
                dragInstructionsId={instructionsId + '-drag-instructions'}
                onDelete={(bId, lId) => deleteLane.mutate({ boardId: bId, laneId: lId })}
              />
            ))}
          </div>
        </SortableContext>
        <DragOverlay>
          {activeItem?.type === 'card' && <CardDragPreview card={activeItem.item} />}
          {activeItem?.type === 'lane' && <LaneDragPreview lane={activeItem.item} />}
        </DragOverlay>
      </DndContext>
      {canModify && <AddLaneForm boardId={board.id} />}
    </>
  )
}

import { useState } from 'react'
import { useSortable, SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    touchAction: 'none',
  },
  laneGhost: {
    opacity: 0.4,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  dragInstructionsId?: string
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, dragInstructionsId, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)
  const [editDialogOpen, setEditDialogOpen] = useState(false)
  const [deletingCard, setDeletingCard] = useState<Card | null>(null)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: lane.id,
    disabled: !canModify,
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition: transition ?? undefined,
  }

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)
  const cardIds = sortedCards.map((c) => c.id)

  const openEdit = (card: Card) => {
    setEditingCard(card)
    setEditDialogOpen(true)
  }

  const openDelete = (card: Card) => {
    setDeletingCard(card)
    setDeleteDialogOpen(true)
  }

  return (
    <section
      ref={setNodeRef}
      className={`${styles.lane}${isDragging ? ` ${styles.laneGhost}` : ''}`}
      style={style}
      aria-label={`Lane: ${lane.name}`}
    >
      <div className={styles.header}>
        <Title2 as="h2" aria-label={`Lane: ${lane.name}`}>
          {lane.name}
        </Title2>
        {canModify && (
          <>
            <Button
              size="small"
              appearance="subtle"
              aria-label={`Drag to reorder lane ${lane.name}`}
              {...attributes}
              {...listeners}
              data-drag-handle=""
            >
              ⠿
            </Button>
            <Button
              size="small"
              appearance="subtle"
              aria-label={`Delete lane ${lane.name}`}
              onClick={() => onDelete(lane.boardId, lane.id)}
            >
              Delete
            </Button>
          </>
        )}
      </div>
      <SortableContext items={cardIds} strategy={verticalListSortingStrategy}>
        <div className={styles.cards}>
          {sortedCards.length === 0 && !canModify && (
            <div className={styles.emptySlot} aria-hidden="true" />
          )}
          {sortedCards.map((card) => (
            <CardItem
              key={card.id}
              card={card}
              callerRole={callerRole}
              dragInstructionsId={dragInstructionsId}
              onEdit={openEdit}
              onDelete={openDelete}
            />
          ))}
        </div>
      </SortableContext>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          key={editingCard.id}
          card={editingCard}
          open={editDialogOpen}
          onClose={() => setEditDialogOpen(false)}
        />
      )}
      {deletingCard && (
        <CardDetailDialog
          key={`delete-${deletingCard.id}`}
          card={deletingCard}
          open={deleteDialogOpen}
          onClose={() => setDeleteDialogOpen(false)}
          initialConfirmDelete={true}
        />
      )}
    </section>
  )
}
